// Another register stage.
reg [2:0] stage3;
// Functional combinational circuit that determines the next stage's output
// given the current stage's output and the input.
reg [2:0] func (input [2:0] stage, input a);
  begin
    case (stage)
      3'b000: if (a) return 3'b001; else return 3'b000;
      3'b001: if (a) return 3'b010; else return 3'b000;
      3'b010: if (a) return 3'b011; else return 3'b000;
      3'b011: if (a) return 3'b100; else return 3'b000;
      3'b100: if (a) return 3'b101; else return 3'b001;
      3'b101: if (a) return 3'b110; else return 3'b001;
      3'b110: if (a) return 3'b111; else return 3'b001;
      3'b111: if (a) return 3'b000; else return 3'b001;
      default: $display("Invalid stage value");
    endcase
  end
// The top-level module.
module TopModule (input clk, input a, output [2:0] q);
  always @(posedge clk) begin
    stage1 <= func(3'b000, a);
    stage2 <= func(stage1, a);
    stage3 <= func(stage2, a);
  end
  assign q = stage3;
endmodule

